// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.sttimport com.roshan.persona.voice.capture.AudioCapturePipelineimport kotlinx.coroutines.flow.Flow/** * NOUS — STT Engine identifier. * * Identifies which speech-to-text engine produced a result. Used for * telemetry, debugging, and confidence calibration (different engines * have different confidence distributions). * * Strategy §5.3 — Hybrid STT: Cloud (Tier 1) → Whisper (Tier 2) → Vosk (Tier 3). */enum class SttEngineType(val displayName: String) {    /** Android system SpeechRecognizer (cloud-backed, Tier 1). */    CLOUD("Android SpeechRecognizer"),    /** Whisper.cpp offline engine (Tier 2, >95% accuracy). */    OFFLINE_WHISPER("Whisper.cpp"),    /** Vosk offline engine (Tier 3, ~90% accuracy, faster). */    OFFLINE_VOSK("Vosk"),    /** Mock engine for unit tests. */    MOCK("Mock"),    ;}/** * NOUS — STT Trust Level. * * Confidence is critical for brain's trust-level routing (Strategy §5.3): *   - > 0.85: HIGH trust — process normally *   - 0.60-0.85: MEDIUM trust — ask for confirmation on critical intents *   - < 0.60: LOW trust — ask user to repeat */enum class SttTrustLevel {    HIGH,    // confidence > 0.85    MEDIUM,  // confidence 0.60 - 0.85    LOW,     // confidence < 0.60    ;    companion object {        /** Classify a confidence score (0.0-1.0) into a trust level. */        fun fromConfidence(confidence: Float): SttTrustLevel = when {            confidence >= 0.85f -> HIGH            confidence >= 0.60f -> MEDIUM            else -> LOW        }    }}// ─── Extension properties on SttResult (backward compat with old data class) ─/** * The transcribed text (empty string for Error results). * * Provides a uniform `text` accessor across all SttResult variants, * simplifying call sites that don't need to distinguish Partial/Final/Error. */val SttResult.text: String    get() = when (this) {        is SttResult.Partial -> this.text        is SttResult.Final -> this.text        is SttResult.Error -> ""    }/** Whether this is a final (end-of-turn) result. */val SttResult.isFinal: Boolean    get() = this is SttResult.Final/** Whether this is an error result. */val SttResult.isError: Boolean    get() = this is SttResult.Error/** Whether this result contains any transcribed text (non-empty). */val SttResult.isEmpty: Boolean    get() = text.isBlank()/** Trust level derived from confidence score. */val SttResult.trustLevel: SttTrustLevel    get() = SttTrustLevel.fromConfidence(confidence)/** * Which STT engine produced this result. * * Note: the sealed interface doesn't carry engine info (it's engine-agnostic). * This extension returns MOCK by default. Call sites that need to track the * engine should use the StreamingSttEngine's `currentEngine` property instead. */val SttResult.engine: SttEngineType    get() = SttEngineType.MOCK/** Whether the result was produced offline (no network). */val SttResult.isOffline: Boolean    get() = when (this) {        is SttResult.Error -> this.reason == SttResult.Error.Reason.MODEL_CRASH        else -> false    }/** * Common interface for all STT engines (cloud + offline). * * Both [CloudSttEngine] and [OfflineSttEngine] extend this interface so that * [StreamingSttEngine] can treat them polymorphically. */interface SttEngine {    suspend fun recognize(        audioStream: Flow<AudioCapturePipeline.AudioChunk>,        confidenceScorer: SttConfidenceScorer,    ): Flow<SttResult>    suspend fun cancel()}